import{_ as t,o as a,c as i,a0 as n}from"./chunks/framework.DYS8d9tm.js";const g=JSON.parse('{"title":"🏗️ Advanced Modular Stack Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/advanced_stack.md","filePath":"deployment/advanced_stack.md"}'),o={name:"deployment/advanced_stack.md"};function s(d,e,l,r,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="🏗️-advanced-modular-stack-deployment" tabindex="-1">🏗️ Advanced Modular Stack Deployment <a class="header-anchor" href="#🏗️-advanced-modular-stack-deployment" aria-label="Permalink to &quot;🏗️ Advanced Modular Stack Deployment&quot;">​</a></h1><p>The WealthFam <strong>Advanced Stack</strong> is the definitive orchestration pattern for production environments. Unlike the monolithic single-container setup, this stack decouples the <strong>Backend</strong>, <strong>WebApp</strong>, and <strong>Parser</strong> into independent microservices.</p><hr><h2 id="💎-why-choose-modular" tabindex="-1">💎 Why Choose Modular? <a class="header-anchor" href="#💎-why-choose-modular" aria-label="Permalink to &quot;💎 Why Choose Modular?&quot;">​</a></h2><ul><li><strong>Isolated Scaling</strong>: Scale the <code>parser</code> independently to handle high-volume SMS/Email ingestion.</li><li><strong>Fault Isolation</strong>: A crash in the front-end Nginx won&#39;t affect the back-end AI processing.</li><li><strong>CI/CD Parity</strong>: Each repository has its own GitHub Action pushing to the <code>wglabz</code> namespace on Docker Hub.</li><li><strong>Dedicated Port Management</strong>: Fine-grained control over exposure for each service.</li></ul><hr><h2 id="🏗️-the-orchestration-blueprint" tabindex="-1">🏗️ The Orchestration Blueprint <a class="header-anchor" href="#🏗️-the-orchestration-blueprint" aria-label="Permalink to &quot;🏗️ The Orchestration Blueprint&quot;">​</a></h2><p>The stack is managed via a unified <code>docker-compose.yml</code> located in the <code>Infra/advanced-stack/</code> directory.</p><h3 id="🌐-internal-networking" tabindex="-1">🌐 Internal Networking <a class="header-anchor" href="#🌐-internal-networking" aria-label="Permalink to &quot;🌐 Internal Networking&quot;">​</a></h3><p>The services communicate over an isolated bridge network:</p><ul><li><code>wglabz-net</code>: Private network for inter-container traffic.</li><li><strong>DNS &amp; REST Resolution</strong>: The consumer WebApp proxies <code>/api</code> and <code>/ws/</code> strictly to <code>http://backend:8000</code> (with zero direct <code>/parser</code> exposure). <code>backend</code> talks internally to <code>http://parser:8001</code> (<code>PARSER_SERVICE_URL</code>) and proxies anonymized training previews/samples to <code>http://admin-backend:8002</code> (<code>ADMIN_SERVICE_URL</code>), <code>admin-web</code> proxies <code>/admin-api/</code> to <code>http://admin-backend:8002/v1/</code>, and <code>admin-backend</code> communicates with <code>backend</code> and <code>parser</code> strictly via REST.</li></ul><h3 id="📊-data-persistence-security-context" tabindex="-1">📊 Data Persistence &amp; Security Context <a class="header-anchor" href="#📊-data-persistence-security-context" aria-label="Permalink to &quot;📊 Data Persistence &amp; Security Context&quot;">​</a></h3><p>The microservices utilize shared <code>/data</code> and PostgreSQL storage layouts under hardened, unprivileged execution:</p><ul><li><code>wglabz-data</code> volume: Mounted to <code>/data</code> across containers (<code>user: &quot;10001:10001&quot;</code>). Used by <code>parser</code> (<code>ingestion_engine_parser.duckdb</code>), <code>admin-backend</code> (<code>telemetry.duckdb</code> &amp; <code>/data/logos/</code>), and <code>backend</code> (<code>/data/vault/</code>, <code>/data/logos/</code>, and <code>/data/backups/</code>).</li><li><code>wglabz-pgdata</code> volume: Managed exclusively by <code>db</code> for <code>backend</code> (<code>wealthfam</code> ledger + <code>brand_logos</code>).</li><li><strong>Non-Root Execution</strong>: Microservice containers run as dedicated unprivileged <code>appuser:appgroup</code> (<code>10001:10001</code>), and WebApp/Admin-Web run as unprivileged <code>nginx</code> (<code>101:101</code>).</li><li><strong>Automated Snapshots</strong>: Daily disaster recovery backup routine runs automatically at 03:30 UTC via APScheduler, creating compressed archives with SHA-256 manifests in <code>/data/backups</code>.</li></ul><hr><h2 id="🚀-deployment-guide" tabindex="-1">🚀 Deployment Guide <a class="header-anchor" href="#🚀-deployment-guide" aria-label="Permalink to &quot;🚀 Deployment Guide&quot;">​</a></h2><h3 id="_1-prerequisites" tabindex="-1">1. Prerequisites <a class="header-anchor" href="#_1-prerequisites" aria-label="Permalink to &quot;1. Prerequisites&quot;">​</a></h3><ul><li>Docker &amp; Docker Compose installed.</li><li>Repositories created on Docker Hub under the <code>wglabz</code> organization.</li></ul><h3 id="_2-configuration-env" tabindex="-1">2. Configuration (<code>.env</code>) <a class="header-anchor" href="#_2-configuration-env" aria-label="Permalink to &quot;2. Configuration (\`.env\`)&quot;">​</a></h3><p>Create a <code>.env</code> file in <code>Infra/advanced-stack/</code> with the following:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SECRET_KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=yoursecretkey</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DOCKER_ORG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=wglabz</span></span></code></pre></div><h3 id="_3-launching-the-hub" tabindex="-1">3. Launching the Hub <a class="header-anchor" href="#_3-launching-the-hub" aria-label="Permalink to &quot;3. Launching the Hub&quot;">​</a></h3><p>Run the following command from the root of the ecosystem:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Infra/advanced-stack/docker-compose.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><hr><h2 id="🧬-container-inventory" tabindex="-1">🧬 Container Inventory <a class="header-anchor" href="#🧬-container-inventory" aria-label="Permalink to &quot;🧬 Container Inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Service</th><th style="text-align:left;">Image</th><th style="text-align:left;">Internal Port</th><th style="text-align:left;">External Port</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Backend</strong></td><td style="text-align:left;"><code>ghcr.io/wealthfam/wealthfam-backend</code></td><td style="text-align:left;">8000</td><td style="text-align:left;">8000</td></tr><tr><td style="text-align:left;"><strong>Parser</strong></td><td style="text-align:left;"><code>ghcr.io/wealthfam/wealthfam-parser</code></td><td style="text-align:left;">8001</td><td style="text-align:left;">8001</td></tr><tr><td style="text-align:left;"><strong>Admin-Backend</strong></td><td style="text-align:left;"><code>ghcr.io/wealthfam/wealthfam-admin</code></td><td style="text-align:left;">8002</td><td style="text-align:left;">8002</td></tr><tr><td style="text-align:left;"><strong>WebApp</strong></td><td style="text-align:left;"><code>ghcr.io/wealthfam/wealthfam-webapp</code></td><td style="text-align:left;">8080</td><td style="text-align:left;">80</td></tr><tr><td style="text-align:left;"><strong>Admin-Web</strong></td><td style="text-align:left;"><code>ghcr.io/wealthfam/wealthfam-admin-web</code></td><td style="text-align:left;">8080</td><td style="text-align:left;">8080</td></tr><tr><td style="text-align:left;"><strong>Database</strong></td><td style="text-align:left;"><code>postgres:15-alpine</code></td><td style="text-align:left;">5432</td><td style="text-align:left;">5432</td></tr></tbody></table><hr><h2 id="🛡️-maintenance-logs" tabindex="-1">🛡️ Maintenance &amp; Logs <a class="header-anchor" href="#🛡️-maintenance-logs" aria-label="Permalink to &quot;🛡️ Maintenance &amp; Logs&quot;">​</a></h2><p>To view the live lifecycle of your modular stack:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># View all service logs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check independent service health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;name=wglabz&quot;</span></span></code></pre></div><hr><div align="center"> *Engineering Excellence · Modular Scalability · Precision Integrity* </div>`,33)])])}const k=t(o,[["render",s]]);export{g as __pageData,k as default};
